begin;
insert into public.accounts(id) values ('00000000-0000-4000-8000-000000000001');
insert into public.catalogs(id) values ('00000000-0000-4000-8000-000000000002');
insert into public.songs(isrc) values ('USAAA2400001');
insert into public.account_catalogs(account,catalog) values ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002');
insert into public.catalog_songs(song,catalog) values ('USAAA2400001','00000000-0000-4000-8000-000000000002');
insert into public.catalog_stream_tracking(catalog_id,owner_id,enabled) values ('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001',true);
set local role service_role;
do $$
declare c uuid := '00000000-0000-4000-8000-000000000002'; r public.catalog_stream_runs; r2 public.catalog_stream_runs; rev uuid;
  result jsonb := '{"state":"partial","provider_recording_id":"MR-test","source_hash":"test-hash","retrieved_at":"2026-10-09T09:00:00Z","days":[{"date":"2026-10-06","streams":1},{"date":"2026-10-07","streams":0}]}'::jsonb;
begin
  if has_table_privilege('anon','public.catalog_stream_observations','select') or has_function_privilege('authenticated','public.claim_catalog_stream_run(uuid,date)','execute') then raise exception 'Browser access'; end if;
  select * into r from public.claim_catalog_stream_run(c,'2026-10-09');
  if r.id is null or r.since <> '2026-08-07' or r.until <> '2026-10-07' then raise exception 'Claim window'; end if;
  if exists(select 1 from public.claim_catalog_stream_run(c,'2026-10-09')) then raise exception 'Duplicate claim'; end if;
  if not public.commit_catalog_stream_track(r.id,'USAAA2400001',result) then raise exception 'Commit failed'; end if;
  if (select count(*) from public.catalog_stream_observations where run_id=r.id) <> 62 then raise exception 'Missing-day preservation'; end if;
  if (select streams from public.catalog_stream_observations where run_id=r.id and date='2026-10-07') <> 0 then raise exception 'Zero preservation'; end if;
  if (select streams from public.catalog_stream_observations where run_id=r.id and date='2026-10-05') is not null then raise exception 'Invented zero'; end if;
  perform public.commit_catalog_stream_track(r.id,'USAAA2400001',result);
  if (select count(*) from public.catalog_stream_observations where run_id=r.id) <> 62 then raise exception 'Retry duplicates'; end if;
  select * into r2 from public.claim_catalog_stream_run(c,'2026-10-10');
  perform public.commit_catalog_stream_track(r2.id,'USAAA2400001',jsonb_set(jsonb_set(result,'{retrieved_at}','"2026-10-10T09:00:00Z"'),'{days}','[{"date":"2026-10-06","streams":2}]'));
  if (select count(*) from public.catalog_stream_observations where run_id=r2.id) <> 3 then raise exception 'Unchanged days copied instead of reusing history'; end if;
  if (select streams from public.read_catalog_stream_days(c,'USAAA2400001','2026-10-06','2026-10-08') where date='2026-10-06') <> 2 then raise exception 'Correction lost'; end if;
  if (select streams from public.read_catalog_stream_days(c,'USAAA2400001','2026-10-06','2026-10-08') where date='2026-10-07') is not null then raise exception 'Old zero filled new missing date'; end if;
  if (select streams from public.catalog_stream_observations where run_id=r.id and date='2026-10-06') <> 1 then raise exception 'Historical version overwritten'; end if;
  update public.catalog_stream_tracking set enabled=false where catalog_id=c;
  if public.commit_catalog_stream_track(r2.id,'USAAA2400001',result) then raise exception 'Disabled write'; end if;
  if exists(select 1 from public.claim_catalog_stream_run(c,'2026-10-11')) then raise exception 'Disabled claim'; end if;
  update public.catalog_stream_tracking set enabled=true, revision=gen_random_uuid() where catalog_id=c;
  if public.commit_catalog_stream_track(r2.id,'USAAA2400001',result) then raise exception 'Stale revision'; end if;
  select * into r2 from public.claim_catalog_stream_run(c,'2026-10-11');
  delete from public.catalog_songs where catalog=c;
  if public.commit_catalog_stream_track(r2.id,'USAAA2400001',result) then raise exception 'Removed recording'; end if;
  insert into public.catalog_songs(song,catalog) values ('USAAA2400001',c);
  delete from public.account_catalogs where catalog=c;
  if public.commit_catalog_stream_track(r2.id,'USAAA2400001',result) then raise exception 'Removed owner'; end if;
  if exists(select 1 from public.claim_catalog_stream_run(c,'2026-10-12')) then raise exception 'Orphan claim'; end if;
  delete from public.accounts where id='00000000-0000-4000-8000-000000000001';
  if exists(select 1 from public.catalog_stream_tracking where catalog_id=c) or exists(select 1 from public.catalog_stream_runs where catalog_id=c) or exists(select 1 from public.catalog_stream_observations where catalog_id=c) then raise exception 'Owning account deletion failed to clean up private streams'; end if;
end $$;
rollback;
